// Pfad oder GitHub-Link prüfen
const REPO = 'pg-coe-kmu/coe-factory';
const ERLAUBT = ['contracts/bc2-to-bc3/', 'bc3-engineering-architect/'];

const eingabe = String($input.first().json.pfad || '').trim();
if (!eingabe) throw new Error('Kein Pfad angegeben');

let pfad = eingabe;
const link = eingabe.match(/^https:\/\/(?:github\.com\/([^/]+\/[^/]+)\/blob|raw\.githubusercontent\.com\/([^/]+\/[^/]+))\/([^/]+)\/(.+)$/);
if (link) {
  const repo = link[1] || link[2];
  const zweig = link[3];
  if (repo !== REPO) throw new Error(`Falsches Repo: ${repo}`);
  if (zweig !== 'main') throw new Error(`Nur Zweig main, nicht ${zweig}`);
  pfad = link[4];
} else if (/^https?:/i.test(eingabe)) {
  throw new Error(`Unbekannter Link: ${eingabe}`);
}

pfad = decodeURIComponent(pfad.split(/[?#]/)[0]).replace(/^\/+/, '');
if (pfad.includes('..') || pfad.includes('\\')) throw new Error(`Ungültiger Pfad: ${pfad}`);
if (!pfad.endsWith('.json')) throw new Error(`Nur .json erlaubt: ${pfad}`);
if (!ERLAUBT.some(o => pfad.startsWith(o))) throw new Error(`Ordner nicht erlaubt: ${pfad}`);

return [{
  json: {
    pfad,
    dateiname: pfad.split('/').pop(),
    url: `https://raw.githubusercontent.com/${REPO}/main/${pfad}`,
  },
}];

// echten Dateinamen setzen, BC3-10 braucht ihn
const eingang = $input.first();
const p = $('Pfad prüfen').first().json;
const schluessel = Object.keys(eingang.binary || {})[0];
if (!schluessel) throw new Error('Keine Datei erhalten');

eingang.binary[schluessel].fileName = p.dateiname;
eingang.binary[schluessel].mimeType = 'application/json';

return [{
  json: { quelle: 'github', pfad: p.pfad, dateiname: p.dateiname, url: p.url, geholt_am: new Date().toISOString() },
  binary: eingang.binary,
}];

